                    fetch('data.json?_=' + Date.now()),
                    fetch('latest-brief.md?_=' + Date.now()).catch(() => null)
                ]);

                if (dataRes.ok) {
                    allData = await dataRes.json();
                    renderAll();
                }

                if (briefRes && briefRes.ok) {
                    allData.brief = await briefRes.text();
                    renderBrief();
                }
            } catch (e) {
                console.error('Failed to load data:', e);
                document.getElementById('insightsList').innerHTML = 
                    '<div class="loading">⚠️ Failed to load data. Check data.json endpoint.</div>';
            }
        }

        function renderAll() {
            renderStats();
            renderSenators();
            renderInsights();
        }

        function renderStats() {
            document.getElementById('totalEntries').textContent = allData.insights?.length || 0;
            document.getElementById('statTotal').textContent = allData.insights?.length || 0;

            const active = allData.senators?.filter(s => s.active).length || 0;
            document.getElementById('statSenators').textContent = active + '/5';

            if (allData.insights?.length > 0) {
                const dates = allData.insights.map(i => i.timestamp).filter(Boolean);
                const latest = dates.sort().pop();
                document.getElementById('lastUpdate').textContent = latest ? latest.split('T')[0] : '-';
                document.getElementById('statBrief').textContent = latest ? latest.split('T')[0] : '-';
            }
        }

        function renderSenators() {
            const grid = document.getElementById('senatorGrid');
            if (!allData.senators?.length) {
                grid.innerHTML = '<div class="loading">No senator data available</div>';
                return;
            }
            grid.innerHTML = allData.senators.map(s => `
                <div class="senator-card">
                    <div class="name">${s.name}</div>
                    <div class="domain">${s.key?.split('/')[0] || 'unknown'}</div>
                    <div class="status ${s.active ? 'active' : 'inactive'}">
                        ${s.active ? '● Active' : '○ Inactive'}
                    </div>
                    <div class="last-update">Last: ${s.last_update || 'Never'}</div>
                </div>
            `).join('');
        }

        function renderInsights(filtered) {
            const list = document.getElementById('insightsList');
            const items = filtered || allData.insights || [];

            if (!items.length) {
                list.innerHTML = '<div class="loading">No insights available</div>';
                return;
            }

            list.innerHTML = items.map(item => {
                const sentiment = detectSentiment(item.summary);
                return `
                    <div class="insight-card" data-sentiment="${sentiment}" data-domain="${item.source?.replace('senator-', '') || 'unknown'}">
                        <div class="insight-meta">
                            <span>${item.source || 'unknown'}</span>
                            <span class="sentiment-${sentiment}">${sentiment}</span>
                            <span>${item.timestamp?.split('T')[0] || '-'}</span>
                        </div>
                        <div class="insight-summary">${escapeHtml(item.summary?.substring(0, 300) || 'No summary')}</div>
                    </div>
                `;
            }).join('');
        }

        function renderBrief() {
            const content = document.getElementById('briefContent');
            if (allData.brief) {
                content.innerHTML = '<div class="brief-content">' + escapeHtml(allData.brief) + '</div>';
            }
        }

        function detectSentiment(text) {
            if (!text) return 'netral';
            const t = text.toLowerCase();
            if (t.includes('positif') || t.includes('naik') || t.includes('tumbuh') || return 'positif';
            if (t.includes('negatif') || t.includes('turun') || t.includes('risiko') || t.includes('burnout')) return 'negatif';
            return 'netral';
        }

        function applyFilters() {
            const domain = document.getElementById('filterDomain').value;
            const sentiment = document.getElementById('filterSentiment').value;
            const date = document.getElementById('filterDate').value;

            let filtered = allData.insights || [];

            if (domain !== 'all') {
                filtered = filtered.filter(i => i.source?.includes(domain));
            }
            if (sentiment !== 'all') {
                filtered = filtered.filter(i => detectSentiment(i.summary) === sentiment);
            }
            if (date) {
                filtered = filtered.filter(i => i.timestamp?.startsWith(date));
            }

            renderInsights(filtered);
        }

        function exportJSON() {
            const blob = new Blob([JSON.stringify(allData, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `pentahelix-export-${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            URL.revokeObjectURL(url);
